package com.kakaplywoods.crm;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api") public class LeadController {
 private final LeadRepository leads;private final ActivityRepository activities;
 public LeadController(LeadRepository leads,ActivityRepository activities){this.leads=leads;this.activities=activities;}
 public record LeadRequest(@NotBlank @Size(max=120) String name,@NotBlank @Pattern(regexp="[0-9+() .-]{7,24}") String phone,@Email @Size(max=254) String email,@Size(max=120) String productInterest,@Size(max=2000) String message,String source,String status,String assignedTo,String followUpAt){}
 public record ActivityRequest(@NotBlank @Size(max=2000) String content,String type){}
 @PostMapping("/public/leads") public ResponseEntity<?> publicLead(@Valid @RequestBody LeadRequest r){Lead l=new Lead();apply(l,r,false);l.setSource("WEBSITE");l.setStatus("NEW");Lead saved=leads.save(l);activities.save(new LeadActivity(saved.getId(),"CREATED","Website enquiry received"));return ResponseEntity.status(201).body(Map.of("leadCode",saved.getLeadCode(),"message","Enquiry received"));}
 @GetMapping("/admin/leads") public List<Map<String,Object>> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String assignedTo){return leads.search(blank(q),blank(status),blank(assignedTo)).stream().map(this::dto).toList();}
 @GetMapping("/admin/leads/{id}") public Map<String,Object> detail(@PathVariable UUID id){Lead l=find(id);Map<String,Object> d=dto(l);d.put("activities",activities.findByLeadIdOrderByCreatedAtDesc(id).stream().map(a->Map.of("id",a.getId(),"type",a.getType(),"content",a.getContent(),"createdAt",a.getCreatedAt())).toList());return d;}
 @PostMapping("/admin/leads") public ResponseEntity<?> create(@Valid @RequestBody LeadRequest r){Lead l=new Lead();apply(l,r,true);Lead saved=leads.save(l);activities.save(new LeadActivity(saved.getId(),"CREATED","Lead created by admin"));return ResponseEntity.status(201).body(dto(saved));}
 @PatchMapping("/admin/leads/{id}") public Map<String,Object> patch(@PathVariable UUID id,@RequestBody Map<String,Object> patch){Lead l=find(id);if(patch.containsKey("name"))l.setName(str(patch,"name"));if(patch.containsKey("phone"))l.setPhone(str(patch,"phone"));if(patch.containsKey("email"))l.setEmail(str(patch,"email"));if(patch.containsKey("productInterest"))l.setProductInterest(str(patch,"productInterest"));if(patch.containsKey("message"))l.setMessage(str(patch,"message"));if(patch.containsKey("status")){String s=str(patch,"status");if(!List.of("NEW","CONTACTED","QUALIFIED","QUOTATION","NEGOTIATION","WON","LOST").contains(s))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");l.setStatus(s);}if(patch.containsKey("assignedTo"))l.setAssignedTo(str(patch,"assignedTo"));if(patch.containsKey("owner"))l.setAssignedTo(str(patch,"owner"));if(patch.containsKey("followUpAt")){String v=str(patch,"followUpAt");l.setFollowUpAt(v.isBlank()||v.equals("—")?null:OffsetDateTime.parse(v));}if(patch.containsKey("follow")){String v=str(patch,"follow");l.setFollowUpAt(v.isBlank()||v.equals("—")?null:LocalDate.parse(v).atStartOfDay().atOffset(ZoneOffset.UTC));}Lead saved=leads.save(l);activities.save(new LeadActivity(saved.getId(),"UPDATED","Lead updated"));return dto(saved);}
 @PostMapping("/admin/leads/{id}/activities") public ResponseEntity<?> addActivity(@PathVariable UUID id,@Valid @RequestBody ActivityRequest r){find(id);LeadActivity a=activities.save(new LeadActivity(id,r.type()==null?"NOTE":r.type(),r.content()));return ResponseEntity.status(201).body(Map.of("id",a.getId(),"content",a.getContent()));}
 @GetMapping("/admin/dashboard") public Map<String,Object> dashboard(){Map<String,Long> pipeline=new LinkedHashMap<>();for(String s:List.of("NEW","CONTACTED","QUALIFIED","QUOTATION","NEGOTIATION","WON","LOST"))pipeline.put(s,leads.countByStatus(s));return Map.of("total",leads.count(),"pipeline",pipeline,"followUpsDue",0L);}
 private Lead find(UUID id){return leads.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Lead not found"));}
 private void apply(Lead l,LeadRequest r,boolean admin){l.setName(r.name().trim());l.setPhone(r.phone().trim());l.setEmail(blank(r.email()));l.setProductInterest(blank(r.productInterest()));l.setMessage(blank(r.message()));if(admin){l.setSource(blank(r.source())==null?"ADMIN":r.source());if(blank(r.status())!=null)l.setStatus(r.status());l.setAssignedTo(blank(r.assignedTo()));if(blank(r.followUpAt())!=null)l.setFollowUpAt(OffsetDateTime.parse(r.followUpAt()));}}
 private Map<String,Object> dto(Lead l){Map<String,Object> m=new LinkedHashMap<>();m.put("id",l.getId());m.put("leadCode",l.getLeadCode());m.put("name",l.getName());m.put("phone",l.getPhone());m.put("email",l.getEmail());m.put("productInterest",l.getProductInterest());m.put("product",l.getProductInterest());m.put("message",l.getMessage());m.put("source",l.getSource());m.put("status",l.getStatus());m.put("assignedTo",l.getAssignedTo());m.put("owner",l.getAssignedTo());m.put("followUpAt",l.getFollowUpAt());m.put("follow",l.getFollowUpAt()==null?"—":l.getFollowUpAt().toLocalDate().toString());m.put("createdAt",l.getCreatedAt());return m;}
 private String blank(String s){return s==null||s.isBlank()?null:s.trim();}private String str(Map<String,Object> m,String k){Object v=m.get(k);return v==null?"":v.toString();}
}
